  "This person also belongs to another society, so only they can change their name, email or phone": "ਇਹ ਵਿਅਕਤੀ ਕਿਸੇ ਹੋਰ ਸੋਸਾਇਟੀ ਨਾਲ ਵੀ ਜੁੜਿਆ ਹੈ, ਇਸ ਲਈ ਸਿਰਫ਼ ਉਹ ਹੀ ਆਪਣਾ ਨਾਮ, ਈਮੇਲ ਜਾਂ ਫ਼ੋਨ ਬਦਲ ਸਕਦੇ ਹਨ",
  "This person also belongs to another society. Ask them to use \"Forgot password\" / SMS login instead.": "ਇਹ ਵਿਅਕਤੀ ਕਿਸੇ ਹੋਰ ਸੋਸਾਇਟੀ ਨਾਲ ਵੀ ਜੁੜਿਆ ਹੈ। ਉਨ੍ਹਾਂ ਨੂੰ \"ਪਾਸਵਰਡ ਭੁੱਲ ਗਏ\" / SMS ਲੌਗਇਨ ਵਰਤਣ ਲਈ ਕਹੋ।",
