  "Who may open the account of someone below them. Every session needs the person's own password, a reason, and is logged.": "ਕੌਣ ਆਪਣੇ ਤੋਂ ਹੇਠਲੇ ਕਿਸੇ ਵਿਅਕਤੀ ਦਾ ਖਾਤਾ ਖੋਲ੍ਹ ਸਕਦਾ ਹੈ। ਹਰ ਸੈਸ਼ਨ ਲਈ ਵਿਅਕਤੀ ਦਾ ਆਪਣਾ ਪਾਸਵਰਡ ਅਤੇ ਕਾਰਨ ਲੋੜੀਂਦਾ ਹੈ, ਅਤੇ ਹਰ ਸੈਸ਼ਨ ਦਰਜ ਹੁੰਦਾ ਹੈ।",
